          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: на малюнку 6.1 (с. 27) у формулах трьох амінокислот знайди амінну, карбоксильну групи і радикал. У якої з амінокислот радикал найпростіший? Яка з них містить Сульфур.</p>",
