          "type": "single",
          "topic": "§ 6. Амінокислоти. Білки",
          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: при термічних опіках рекомендують тривале охолодження ураженої ділянки холодною водою. Поясни, що відбуваються з білками шкіри під час опіку та охолодження..</p>",
