          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: макромолекули потрапляють у клітину або з клітини у везикулах (міхурцях). Визнач, якою цифрою на малюнку 13.4 позначено ендоцитоз, а якою — екзоцитоз. Наведи приклади транспортування речовин такими способами..</p>",
