          "answerText": "Гліколіз дає чистий вихід двох молекул АТФ із молекули глюкози. Подальше окиснення продуктів гліколізу та перенесення електронів забезпечують утворення набагато більшої кількості АТФ. Електронно-транспортний ланцюг створює протонний градієнт, енергію якого використовує АТФ-синтаза. Тому аеробне окиснення енергетично вигідніше за сам гліколіз. Наведений у підручнику вихід близько 36 АТФ для кисневого етапу є спрощеною навчальною моделлю, а не незмінним точним виходом для всіх клітин.",
