          "type": "single",
          "topic": "§ 18. Розщеплення органічних речовин",
          "questionHtml": "<p>Яке твердження коректно характеризує відстрочений м’язовий біль (крепатуру), що з’являється після незвичного фізичного навантаження?</p>",
