          "correctKey": "А",
          "answerText": "Капсид і ДНК або РНК є обов’язковими складниками віріона; додаткова ліпопротеїнова оболонка властива лише складним вірусам.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
          "sourceFile": "data/flashcards/grade-9/sources/v21/biology-9-v21/Біологія_9_Задорожний_2026_пар_22_ТЕСТИ_05.md"
