          "type": "single",
          "topic": "§ 24. Гени і геноми",
          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: проаналізуй інформацію на малюнку 24.2. Опиши відмінності складу геномів прокаріотів та еукаріотів..</p>",
