          "questionHtml": "<p>У моделі кумулятивної полімерії кожен домінантний алель має однаковий додатковий вплив на висоту. Шість домінантних алелів дають 200 см, а їх відсутність — 140 см. Яку середню висоту очікують для A₁a₁A₂a₂A₃a₃ та A₁A₁A₂a₂a₃a₃?</p>",
