          "answerText": "За кумулятивної полімерії важлива загальна кількість домінантних алелів; в обох генотипах їх по три.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
          "sourceFile": "data/flashcards/grade-9/sources/v21/biology-9-v21/Біологія_9_Задорожний_2026_пар_29_ТЕСТИ_06.md"
