          "type": "single",
          "topic": "§ 30. Цитоплазматична спадковість. Регуляція активності генів",
          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: у кого з родичів однакова мітохондріальна ДНК: а) у чоловіка і дружини; б) у матері та її синів; в) у батька та його синів; г) в онука і бабусі (матері його матері); д) в онучки і бабусі (матері її батька).</p>",
