          "topic": "§ 30. Цитоплазматична спадковість. Регуляція активності генів",
          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: у рослин одного виду спостерігають два варіанти забарвлення листя: А — з білими смугами, Б — суцільне зелене. Якщо рослини А запилити пилком рослин Б, у нащадків листки мають білі смуги. Якщо рослини Б запилюють пилком А, отримують рослин із суцільним зеленим листям. Поясни механізм успадкування..</p>",
