          "questionHtml": "<p>Добери приклади фенотипної мінливості у рослин, тварин, людини. Визнач, якими чинниками зумовлена мінливість.</p>",
          "options": [
            {
              "key": "А",
              "text": "Хлороз або форма листків у рослин залежать від умов росту; зелене забарвлення слимака — від живлення водоростями; м’язова маса людини — від тренувань."
            },
            {
              "key": "Б",
              "text": "Усі наведені зміни обов’язково виникають через генні мутації та передаються нащадкам."
            },
            {
              "key": "В",
              "text": "Фенотипну мінливість у всіх організмів спричиняє лише кросинговер."
            },
            {
              "key": "Г",
              "text": "Умови довкілля не можуть впливати на ознаки рослин, тварин і людини."
            }
          ],
          "correctKey": "А",
          "answerText": "У кожному прикладі ознака змінюється у відповідь на конкретний чинник середовища або спосіб життя без доведеної зміни генотипу.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
