          "answerText": "Частота показує кількість бобів із відповідним числом насінин; сума всіх частот має дорівнювати 30.\n\n[ВСТАВИТИ ГРАФІК: «Варіаційна крива кількості насінин у бобах гороху»; побудовано за даними завдання 5; файл: ../assets/IMG_33.05_01.png]",
