          "questionHtml": "<p>Дай самостійну обґрунтовану відповідь щодо такого: спираючись на малюнок 34.3, поясни зв’язок між індексом маси тіла (ІМТ) і розвитком діабету. (ІМТ = m/h², де m — маса, кг; h — зріст, м)..</p>",
