          "answerText": "Поява ознаки в нащадка двох батьків без її фенотипового прояву є характерною ознакою рецесивного успадкування.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
          "sourceFile": "data/flashcards/grade-9/sources/v21/biology-9-v21/Біологія_9_Задорожний_2026_пар_35_ТЕСТИ_03.md",
