          "sourceCardId": "35.03",
          "type": "single",
          "topic": "§ 35. Генетика людини. Медико-генетичне консультування",
          "questionHtml": "<p>Добери приклади захворювань людини, що спричиняються геномними і генними мутаціями.</p>",
          "options": [
            {
              "key": "А",
              "text": "Геномні: синдром Дауна та зміни числа статевих хромосом; генні: гемофілія, альбінізм, муковісцидоз, фенілкетонурія, серпоподібноклітинна анемія."
            },
            {
              "key": "Б",
              "text": "Геномні: засмага і тренованість; генні: збільшення м’язової маси після навантаження."
            },
            {
              "key": "В",
              "text": "Геномні: лише застуда; генні: усі травми, спричинені зовнішніми факторами."
            },
            {
              "key": "Г",
              "text": "Синдром Дауна спричиняється тільки зміною харчування, а фенілкетонурія — тренуваннями."
            }
          ],
          "correctKey": "А",
          "answerText": "Геномні мутації змінюють кількість хромосом, а генні порушують послідовність конкретного гена та функцію відповідного білка.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
