          "correctKey": "А",
          "answerText": "За нестатевого розмноження немає комбінування генетичного матеріалу двох батьків, тому нащадки переважно є клонами.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
